const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;

pub const OptimizerConfig = struct {
    learning_rate: f32 = 1e-3,
    beta1: f32 = 0.9,
    beta2: f32 = 0.999,
    epsilon: f32 = 1e-8,
    weight_decay: f32 = 0.01,
    amsgrad: bool = false,
    maximize: bool = false,
    capturable: bool = false,
    differentiable: bool = false,
    fused: ?bool = null,
    heuristic_momentum_window: u32 = 10,
    state_matrix_regularization: f32 = 0.01,
    adaptive_lr_scaling: bool = true,
    gradient_centralization: bool = false,
    lookahead: bool = false,
    lookahead_k: u32 = 5,
    lookahead_alpha: f32 = 0.5,
};

pub const ParameterState = struct {
    step: u64,
    exp_avg: []f32,
    exp_avg_sq: []f32,
    max_exp_avg_sq: ?[]f32,
    gradient_history: [][]f32,
    lookahead_params: ?[]f32,

    const Self = @This();

    pub fn init(allocator: Allocator, param_size: usize, config: OptimizerConfig) !Self {
        var exp_avg = try allocator.alloc(f32, param_size);
        var exp_avg_sq = try allocator.alloc(f32, param_size);
        std.mem.set(f32, exp_avg, 0.0);
        std.mem.set(f32, exp_avg_sq, 0.0);

        var max_exp_avg_sq: ?[]f32 = null;
        if (config.amsgrad) {
            max_exp_avg_sq = try allocator.alloc(f32, param_size);
            std.mem.set(f32, max_exp_avg_sq.?, 0.0);
        }

        var gradient_history = try allocator.alloc([]f32, config.heuristic_momentum_window);
        for (0..config.heuristic_momentum_window) |i| {
            gradient_history[i] = try allocator.alloc(f32, param_size);
            std.mem.set(f32, gradient_history[i], 0.0);
        }

        var lookahead_params: ?[]f32 = null;
        if (config.lookahead) {
            lookahead_params = try allocator.alloc(f32, param_size);
            std.mem.set(f32, lookahead_params.?, 0.0);
        }

        return Self{
            .step = 0,
            .exp_avg = exp_avg,
            .exp_avg_sq = exp_avg_sq,
            .max_exp_avg_sq = max_exp_avg_sq,
            .gradient_history = gradient_history,
            .lookahead_params = lookahead_params,
        };
    }

    pub fn deinit(self: *Self, allocator: Allocator) void {
        allocator.free(self.exp_avg);
        allocator.free(self.exp_avg_sq);

        if (self.max_exp_avg_sq) |max_sq| {
            allocator.free(max_sq);
        }

        for (self.gradient_history) |hist| {
            allocator.free(hist);
        }
        allocator.free(self.gradient_history);

        if (self.lookahead_params) |params| {
            allocator.free(params);
        }
    }
};

pub const HeuristicGradientMomentumOptimizer = struct {
    allocator: Allocator,
    config: OptimizerConfig,
    param_states: std.HashMap(usize, ParameterState, std.hash_map.DefaultContext(usize), std.hash_map.default_max_load_percentage),
    global_step: u64,

    const Self = @This();

    pub fn init(allocator: Allocator, config: OptimizerConfig) Self {
        return Self{
            .allocator = allocator,
            .config = config,
            .param_states = std.HashMap(usize, ParameterState, std.hash_map.DefaultContext(usize), std.hash_map.default_max_load_percentage).init(allocator),
            .global_step = 0,
        };
    }

    pub fn deinit(self: *Self) void {
        var iterator = self.param_states.iterator();
        while (iterator.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.param_states.deinit();
    }

    pub fn step(self: *Self, parameters: [][]f32, gradients: [][]f32, is_state_matrix: []bool) !void {
        self.global_step += 1;

        for (parameters, gradients, is_state_matrix, 0..) |*param, grad, is_state, param_idx| {
            try self.updateParameter(param, grad, is_state, param_idx);
        }

        // Apply lookahead if enabled
        if (self.config.lookahead and self.global_step % self.config.lookahead_k == 0) {
            try self.applyLookahead(parameters);
        }
    }

    fn updateParameter(self: *Self, parameter: *[]f32, gradient: []f32, is_state_matrix: bool, param_idx: usize) !void {
        const param_size = parameter.len;

        // Get or create parameter state
        var state = self.param_states.get(param_idx);
        if (state == null) {
            const new_state = try ParameterState.init(self.allocator, param_size, self.config);
            try self.param_states.put(param_idx, new_state);
            state = self.param_states.get(param_idx);
        }

        var param_state = &state.?;
        param_state.step += 1;

        // Apply gradient centralization if enabled
        var centralized_grad = try self.allocator.alloc(f32, param_size);
        defer self.allocator.free(centralized_grad);

        if (self.config.gradient_centralization and param_size > 1) {
            const grad_mean = self.computeMean(gradient);
            for (0..param_size) |i| {
                centralized_grad[i] = gradient[i] - grad_mean;
            }
        } else {
            std.mem.copy(f32, centralized_grad, gradient);
        }

        // Update gradient history for heuristic momentum
        const history_idx = param_state.step % self.config.heuristic_momentum_window;
        std.mem.copy(f32, param_state.gradient_history[history_idx], centralized_grad);

        // Compute dynamic beta1 using heuristic momentum
        var dynamic_beta1 = self.config.beta1;
        if (param_state.step > self.config.heuristic_momentum_window) {
            const cosine_similarity = self.computeCosineSimilarity(
                centralized_grad, 
                param_state.gradient_history, 
                self.config.heuristic_momentum_window
            );
            dynamic_beta1 = self.config.beta1 * (1.0 + 0.5 * math.max(0.0, cosine_similarity));
            dynamic_beta1 = math.min(dynamic_beta1, 0.999);
        }

        // Update biased first moment estimate
        for (0..param_size) |i| {
            param_state.exp_avg[i] = dynamic_beta1 * param_state.exp_avg[i] + 
                                   (1.0 - dynamic_beta1) * centralized_grad[i];
        }

        // Update biased second raw moment estimate
        for (0..param_size) |i| {
            param_state.exp_avg_sq[i] = self.config.beta2 * param_state.exp_avg_sq[i] + 
                                       (1.0 - self.config.beta2) * centralized_grad[i] * centralized_grad[i];
        }

        // Update max exponential average if AMSGrad
        if (self.config.amsgrad) {
            if (param_state.max_exp_avg_sq) |max_sq| {
                for (0..param_size) |i| {
                    max_sq[i] = math.max(max_sq[i], param_state.exp_avg_sq[i]);
                }
            }
        }

        // Compute bias correction
        const bias_correction1 = 1.0 - math.pow(f32, dynamic_beta1, @floatFromInt(param_state.step));
        const bias_correction2 = 1.0 - math.pow(f32, self.config.beta2, @floatFromInt(param_state.step));

        // Compute step size
        var step_size = self.config.learning_rate / bias_correction1;

        // Apply adaptive learning rate scaling
        if (self.config.adaptive_lr_scaling) {
            const grad_norm = self.computeNorm(centralized_grad);
            const param_norm = self.computeNorm(parameter.*);
            if (param_norm > 1e-8) {
                const scale_factor = math.min(1.0, 1.0 / (grad_norm / param_norm + 1e-8));
                step_size *= scale_factor;
            }
        }

        // Parameter update
        for (0..param_size) |i| {
            var denominator: f32 = undefined;
            if (self.config.amsgrad and param_state.max_exp_avg_sq != null) {
                denominator = math.sqrt(param_state.max_exp_avg_sq.?[i]) / math.sqrt(bias_correction2) + self.config.epsilon;
            } else {
                denominator = math.sqrt(param_state.exp_avg_sq[i]) / math.sqrt(bias_correction2) + self.config.epsilon;
            }

            var update = step_size * (param_state.exp_avg[i] / denominator);

            // Add weight decay
            if (self.config.weight_decay > 0.0) {
                update += self.config.learning_rate * self.config.weight_decay * parameter.*[i];
            }

            // Apply state matrix regularization for SSM parameters
            if (is_state_matrix and self.config.state_matrix_regularization > 0.0) {
                const param_norm = self.computeNorm(parameter.*);
                if (param_norm > 1.0) {
                    update += self.config.learning_rate * self.config.state_matrix_regularization * parameter.*[i];
                }
            }

            // Apply update
            if (self.config.maximize) {
                parameter.*[i] += update;
            } else {
                parameter.*[i] -= update;
            }
        }

        // Store lookahead parameters
        if (self.config.lookahead) {
            if (param_state.lookahead_params) |lookahead| {
                if (param_state.step == 1) {
                    std.mem.copy(f32, lookahead, parameter.*);
                }
            }
        }
    }

    fn applyLookahead(self: *Self, parameters: [][]f32) !void {
        var iterator = self.param_states.iterator();
        var param_idx: usize = 0;

        while (iterator.next()) |entry| {
            if (param_idx < parameters.len) {
                const state = entry.value_ptr;
                if (state.lookahead_params) |lookahead| {
                    for (0..parameters[param_idx].len) |i| {
                        const diff = parameters[param_idx][i] - lookahead[i];
                        lookahead[i] += self.config.lookahead_alpha * diff;
                        parameters[param_idx][i] = lookahead[i];
                    }
                }
            }
            param_idx += 1;
        }
    }

    fn computeMean(self: *Self, values: []f32) f32 {
        _ = self;
        var sum: f32 = 0.0;
        for (values) |val| {
            sum += val;
        }
        return sum / @as(f32, @floatFromInt(values.len));
    }

    fn computeNorm(self: *Self, values: []f32) f32 {
        _ = self;
        var sum_sq: f32 = 0.0;
        for (values) |val| {
            sum_sq += val * val;
        }
        return math.sqrt(sum_sq);
    }

    fn computeCosineSimilarity(self: *Self, current_grad: []f32, gradient_history: [][]f32, window_size: u32) f32 {
        _ = self;

        // Compute average of historical gradients
        var avg_grad = self.allocator.alloc(f32, current_grad.len) catch return 0.0;
        defer self.allocator.free(avg_grad);

        std.mem.set(f32, avg_grad, 0.0);

        for (0..window_size) |i| {
            for (0..current_grad.len) |j| {
                avg_grad[j] += gradient_history[i][j];
            }
        }

        for (0..current_grad.len) |i| {
            avg_grad[i] /= @as(f32, @floatFromInt(window_size));
        }

        // Compute cosine similarity
        var dot_product: f32 = 0.0;
        var norm_current: f32 = 0.0;
        var norm_avg: f32 = 0.0;

        for (0..current_grad.len) |i| {
            dot_product += current_grad[i] * avg_grad[i];
            norm_current += current_grad[i] * current_grad[i];
            norm_avg += avg_grad[i] * avg_grad[i];
        }

        norm_current = math.sqrt(norm_current);
        norm_avg = math.sqrt(norm_avg);

        if (norm_current < 1e-8 or norm_avg < 1e-8) {
            return 0.0;
        }

        return dot_product / (norm_current * norm_avg);
    }

    pub fn zeroGrad(self: *Self, gradients: [][]f32) void {
        _ = self;
        for (gradients) |grad| {
            std.mem.set(f32, grad, 0.0);
        }
    }

    pub fn getState(self: *Self) OptimizerState {
        return OptimizerState{
            .global_step = self.global_step,
            .param_states_count = @intCast(self.param_states.count()),
        };
    }

    pub fn loadState(self: *Self, state: OptimizerState) void {
        self.global_step = state.global_step;
    }
};

pub const OptimizerState = struct {
    global_step: u64,
    param_states_count: u32,
};

// Learning rate schedulers
pub const LinearWarmupScheduler = struct {
    base_lr: f32,
    warmup_steps: u64,
    total_steps: u64,
    current_step: u64,

    const Self = @This();

    pub fn init(base_lr: f32, warmup_steps: u64, total_steps: u64) Self {
        return Self{
            .base_lr = base_lr,
            .warmup_steps = warmup_steps,
            .total_steps = total_steps,
            .current_step = 0,
        };
    }

    pub fn step(self: *Self) f32 {
        self.current_step += 1;

        if (self.current_step <= self.warmup_steps) {
            // Linear warmup
            return self.base_lr * (@as(f32, @floatFromInt(self.current_step)) / @as(f32, @floatFromInt(self.warmup_steps)));
        } else {
            // Linear decay
            const decay_steps = self.total_steps - self.warmup_steps;
            const progress = @as(f32, @floatFromInt(self.current_step - self.warmup_steps)) / @as(f32, @floatFromInt(decay_steps));
            return self.base_lr * (1.0 - progress);
        }
    }

    pub fn getCurrentLR(self: *Self) f32 {
        if (self.current_step <= self.warmup_steps) {
            return self.base_lr * (@as(f32, @floatFromInt(self.current_step)) / @as(f32, @floatFromInt(self.warmup_steps)));
        } else {
            const decay_steps = self.total_steps - self.warmup_steps;
            const progress = @as(f32, @floatFromInt(self.current_step - self.warmup_steps)) / @as(f32, @floatFromInt(decay_steps));
            return self.base_lr * (1.0 - progress);
        }
    }
};

pub const CosineAnnealingScheduler = struct {
    base_lr: f32,
    min_lr: f32,
    total_steps: u64,
    current_step: u64,

    const Self = @This();

    pub fn init(base_lr: f32, min_lr: f32, total_steps: u64) Self {
        return Self{
            .base_lr = base_lr,
            .min_lr = min_lr,
            .total_steps = total_steps,
            .current_step = 0,
        };
    }

    pub fn step(self: *Self) f32 {
        self.current_step += 1;
        const progress = @as(f32, @floatFromInt(self.current_step)) / @as(f32, @floatFromInt(self.total_steps));
        const cosine_factor = 0.5 * (1.0 + math.cos(math.pi * progress));
        return self.min_lr + (self.base_lr - self.min_lr) * cosine_factor;
    }

    pub fn getCurrentLR(self: *Self) f32 {
        const progress = @as(f32, @floatFromInt(self.current_step)) / @as(f32, @floatFromInt(self.total_steps));
        const cosine_factor = 0.5 * (1.0 + math.cos(math.pi * progress));
        return self.min_lr + (self.base_lr - self.min_lr) * cosine_factor;
    }
};

