  for layer in 0..<numLayers {
    forall (i, j) in StateDomain {
      ssmAAdam1[layer][i, j] = 0.0;
      ssmAAdam2[layer][i, j] = 0.0;
      ssmBAdam1[layer][i, j] = 0.0;
      ssmBAdam2[layer][i, j] = 0.0;
      ssmCAdam1[layer][i, j] = 0.0;
      ssmCAdam2[layer][i, j] = 0.0;
    }
  }

  globalStep.write(0);
  currentEpoch.write(0);

  var startTime = getCurrentTime();

  // Training epochs
  for epoch in 1..numEpochs {
    currentEpoch.write(epoch);
    dataLoader.reset();

    writeln("Starting epoch ", epoch);
    var epochLoss: real = 0.0;
    var epochSteps: int = 0;

    while dataLoader.nextBatch() {
      const step = globalStep.read() + 1;
      globalStep.write(step);

      var batchStartTime = getCurrentTime();

      // Get batch data
      const batchInputs = dataLoader.getBatchData();

      // Create targets (shifted inputs for language modeling)
      var batchTargets: [BatchDomain dmapped BatchDist] int;
      forall (b, t) in BatchDomain {
        batchTargets[b, t] = if t < seqLen - 1 
                            then batchInputs[b, t + 1]
                            else batchInputs[b, 0];
      }

      // Zero gradients
      zeroGradients();

      // Forward pass
      var logits: [BatchDomain dmapped BatchDist] real;

      coforall loc in Locales do on loc {
        const localLogits = model.forward(batchInputs);
        logits = localLogits; // Simplified - would need proper reduction
