        }
      }

      // Gradient accumulation
      if step % gradientAccumSteps == 0 {
        // Synchronize gradients across locales
        synchronizeGradients();

        // Update parameters
        updateParameters();
      }

      var batchEndTime = getCurrentTime();
      var batchTime = batchEndTime - batchStartTime;

      // Logging
      if step % 10 == 0 {
        const tokensPerSec = (batchSize * seqLen) / batchTime;
        writeln("Step ", step, 
               " | Loss: ", batchLoss:real,
               " | Tokens/sec: ", tokensPerSec:int,
               " | Time: ", batchTime:real, "s");
      }

      // Checkpointing
      if step % checkpointEvery == 0 {
        saveCheckpoint(step);
      }

      // Validation
      if step % validateEvery == 0 {
        runValidation(model, step);
      }
    }

    const avgEpochLoss = epochLoss / epochSteps;
    writeln("Epoch ", epoch, " completed | Average loss: ", avgEpochLoss);
  }

  var endTime = getCurrentTime();
  var totalTime = endTime - startTime;

  writeln("Training completed in ", totalTime, " seconds");
  writeln("Final loss: ", trainingLoss.read());

  // Save final model
  saveCheckpoint(globalStep.read());
}

// Validation routine
proc runValidation(ref model: JAIDEModel, step: int) {
  writeln("Running validation at step ", step);

  // Create validation data (simplified)
  var valBatch: [BatchDomain dmapped BatchDist] int;
  forall (i, j) in BatchDomain {
