// JAIDE V25 - Advanced Tensor Operations Hardware Unit
// Implements optimized matrix-vector and tensor operations for SSM computations

`timescale 1ns / 1ps

module tensor_ops_unit #(
    parameter DATA_WIDTH = 16,
    parameter ADDR_WIDTH = 20,
    parameter MAX_TENSOR_SIZE = 1048576,  // 1M elements
    parameter NUM_PES = 256,              // Processing Elements
    parameter FIFO_DEPTH = 1024,
    parameter TERNARY_WIDTH = 2
)(
    input wire clk,
    input wire rst_n,
    input wire enable,

    // Control interface
    input wire [3:0] operation,           // 0: MATMUL, 1: CONV1D, 2: SSM_SCAN, 3: ACTIVATION
    input wire [15:0] tensor_dims [0:3],  // [batch, seq_len, d_model, d_state]
    input wire start,
    output reg done,
    output reg error,

    // Memory interface  
    output reg [ADDR_WIDTH-1:0] mem_addr,
    output reg mem_read_en,
    output reg mem_write_en,
    input wire [DATA_WIDTH-1:0] mem_data_in,
    output reg [DATA_WIDTH-1:0] mem_data_out,

    // DMA interface for high-throughput transfers
    input wire dma_ready,
    output reg dma_request,
    output reg [ADDR_WIDTH-1:0] dma_src_addr,
    output reg [ADDR_WIDTH-1:0] dma_dst_addr,
    output reg [15:0] dma_length,

    // Performance counters
    output reg [31:0] cycles_counter,
    output reg [31:0] operations_counter,
    output reg [31:0] memory_accesses
);

// Operation codes
localparam OP_MATMUL = 4'h0;
localparam OP_CONV1D = 4'h1;
localparam OP_SSM_SCAN = 4'h2;
localparam OP_ACTIVATION = 4'h3;
localparam OP_TRANSPOSE = 4'h4;
localparam OP_REDUCE_SUM = 4'h5;
localparam OP_ELEMENTWISE_MUL = 4'h6;
localparam OP_LAYER_NORM = 4'h7;

// State machine states
typedef enum logic [3:0] {
    IDLE,
    DECODE_OP,
    LOAD_OPERANDS,
    COMPUTE,
    STORE_RESULT,
    DONE_STATE,
    ERROR_STATE
} state_t;

state_t current_state, next_state;

// Internal registers and wires
reg [15:0] batch_size, seq_len, d_model, d_state;
reg [31:0] operation_counter;
reg [ADDR_WIDTH-1:0] operand_a_addr, operand_b_addr, result_addr;
reg [15:0] current_batch, current_seq, current_dim;

// Processing element array
wire [DATA_WIDTH-1:0] pe_data_in [0:NUM_PES-1];
wire [DATA_WIDTH-1:0] pe_data_out [0:NUM_PES-1];
wire [NUM_PES-1:0] pe_valid;
wire [NUM_PES-1:0] pe_ready;

// Internal memory for temporary storage
reg [DATA_WIDTH-1:0] internal_buffer [0:4095];
reg [11:0] buffer_read_addr, buffer_write_addr;
reg buffer_read_en, buffer_write_en;

// FIFO for pipelined operations
wire fifo_empty, fifo_full;
wire [DATA_WIDTH-1:0] fifo_data_out;
reg fifo_read_en, fifo_write_en;
reg [DATA_WIDTH-1:0] fifo_data_in;

// Activation function ROM (for fast lookup)
reg [DATA_WIDTH-1:0] activation_lut [0:1023];
wire [9:0] activation_addr;
wire [DATA_WIDTH-1:0] activation_result;

// Initialize activation LUT with SiLU values
initial begin
    integer i;
    real x, silu_val;
    for (i = 0; i < 1024; i = i + 1) begin
        // Map i to range [-8, 8]
        x = (i - 512.0) / 64.0;
        // Compute SiLU(x) = x / (1 + exp(-x))
        // Approximated using Taylor series for hardware efficiency
        if (x >= 0) begin
            silu_val = x / (1.0 + $exp(-x));
        end else begin
            silu_val = x * $exp(x) / (1.0 + $exp(x));
        end

        // Convert to fixed-point representation
        activation_lut[i] = $rtoi(silu_val * (2**(DATA_WIDTH-8)));
    end
end

// FIFO instance
async_fifo #(
    .DATA_WIDTH(DATA_WIDTH),
    .ADDR_WIDTH($clog2(FIFO_DEPTH))
) data_fifo (
    .wr_clk(clk),
    .rd_clk(clk),
    .rst_n(rst_n),
    .wr_en(fifo_write_en),
    .rd_en(fifo_read_en),
    .data_in(fifo_data_in),
    .data_out(fifo_data_out),
    .empty(fifo_empty),
    .full(fifo_full)
);

// Generate processing elements
genvar pe_idx;
generate
    for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin : gen_pes
        processing_element #(
            .DATA_WIDTH(DATA_WIDTH),
            .PE_ID(pe_idx)
        ) pe_inst (
            .clk(clk),
            .rst_n(rst_n),
            .enable(enable && (current_state == COMPUTE)),
            .data_in(pe_data_in[pe_idx]),
            .data_out(pe_data_out[pe_idx]),
            .valid_out(pe_valid[pe_idx]),
            .ready(pe_ready[pe_idx])
        );
    end
endgenerate

// Main state machine
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
        cycles_counter <= 0;
        operations_counter <= 0;
        memory_accesses <= 0;
        done <= 0;
        error <= 0;
    end else begin
        current_state <= next_state;
        cycles_counter <= cycles_counter + 1;

        if (current_state == COMPUTE) begin
            operations_counter <= operations_counter + NUM_PES;
        end

        if (mem_read_en || mem_write_en) begin
            memory_accesses <= memory_accesses + 1;
        end
    end
end

// State machine logic
always_comb begin
    next_state = current_state;
    done = 0;
    error = 0;

    case (current_state)
        IDLE: begin
            if (start && enable) begin
                next_state = DECODE_OP;
            end
        end

        DECODE_OP: begin
            if (operation <= OP_LAYER_NORM) begin
                next_state = LOAD_OPERANDS;
            end else begin
                next_state = ERROR_STATE;
            end
        end

        LOAD_OPERANDS: begin
            if (operand_loading_complete()) begin
                next_state = COMPUTE;
            end
        end

        COMPUTE: begin
            if (computation_complete()) begin
                next_state = STORE_RESULT;
            end
        end

        STORE_RESULT: begin
            if (result_stored()) begin
                next_state = DONE_STATE;
            end
        end

        DONE_STATE: begin
            done = 1;
            next_state = IDLE;
        end

        ERROR_STATE: begin
            error = 1;
            next_state = IDLE;
        end
    endcase
end

// Operand loading control
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        batch_size <= 0;
        seq_len <= 0;
        d_model <= 0;
        d_state <= 0;
        current_batch <= 0;
        current_seq <= 0;
        current_dim <= 0;
    end else if (current_state == DECODE_OP) begin
        batch_size <= tensor_dims;
        seq_len <= tensor_dims[1];
        d_model <= tensor_dims;
        d_state <= tensor_dims;
        current_batch <= 0;
        current_seq <= 0;
        current_dim <= 0;
    end else if (current_state == LOAD_OPERANDS) begin
        // Update counters for data loading
        if (mem_read_en && dma_ready) begin
            if (current_dim < d_model - 1) begin
                current_dim <= current_dim + 1;
            end else if (current_seq < seq_len - 1) begin
                current_dim <= 0;
                current_seq <= current_seq + 1;
            end else if (current_batch < batch_size - 1) begin
                current_dim <= 0;
                current_seq <= 0;
                current_batch <= current_batch + 1;
            end
        end
    end
end

// Memory address generation
always_comb begin
    mem_addr = 0;
    mem_read_en = 0;
    mem_write_en = 0;

    case (current_state)
        LOAD_OPERANDS: begin
            mem_addr = operand_a_addr + (current_batch * seq_len * d_model) + 
                      (current_seq * d_model) + current_dim;
            mem_read_en = 1;
        end

        STORE_RESULT: begin
            mem_addr = result_addr + (current_batch * seq_len * d_model) + 
                      (current_seq * d_model) + current_dim;
            mem_write_en = 1;
        end
    endcase
end

// Computation engine - dispatches to appropriate operation
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        operation_counter <= 0;
    end else if (current_state == COMPUTE) begin
        case (operation)
            OP_MATMUL: begin
                perform_matrix_multiply();
            end

            OP_CONV1D: begin
                perform_conv1d();
            end

            OP_SSM_SCAN: begin
                perform_ssm_scan();
            end

            OP_ACTIVATION: begin
                perform_activation();
            end

            OP_TRANSPOSE: begin
                perform_transpose();
            end

            OP_REDUCE_SUM: begin
                perform_reduce_sum();
            end

            OP_ELEMENTWISE_MUL: begin
                perform_elementwise_multiply();
            end

            OP_LAYER_NORM: begin
                perform_layer_norm();
            end
        endcase

        operation_counter <= operation_counter + 1;
    end
end

// Matrix multiplication implementation
task perform_matrix_multiply;
    integer pe_idx, row, col;
    reg [DATA_WIDTH-1:0] partial_sum;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                // Assign work to this PE
                row = (operation_counter * NUM_PES + pe_idx) / d_model;
                col = (operation_counter * NUM_PES + pe_idx) % d_model;

                if (row < batch_size && col < d_state) begin
                    // Load data for this PE
                    pe_data_in[pe_idx] = internal_buffer[buffer_read_addr];
                    buffer_read_addr = (buffer_read_addr + 1) % 4096;
                end
            end
        end
    end
endtask

// 1D Convolution implementation
task perform_conv1d;
    integer pe_idx, pos, kernel_pos;
    reg [DATA_WIDTH-1:0] conv_result;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                pos = (operation_counter * NUM_PES + pe_idx);

                if (pos < seq_len) begin
                    conv_result = 0;

                    // Convolution window (simplified 3-point kernel)
                    for (kernel_pos = -1; kernel_pos <= 1; kernel_pos = kernel_pos + 1) begin
                        if ((pos + kernel_pos) >= 0 && (pos + kernel_pos) < seq_len) begin
                            conv_result = conv_result + 
                                internal_buffer[(pos + kernel_pos) % 4096] * 
                                activation_lut[kernel_pos + 1]; // Use LUT as kernel weights
                        end
                    end

                    pe_data_in[pe_idx] = conv_result;
                end
            end
        end
    end
endtask

// SSM selective scan implementation
task perform_ssm_scan;
    integer pe_idx, state_idx;
    reg [DATA_WIDTH-1:0] state_update, input_val, a_val, b_val, c_val, d_val;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                state_idx = pe_idx % d_state;

                // Load SSM parameters (simplified)
                a_val = internal_buffer[state_idx];
                b_val = internal_buffer[d_state + state_idx];
                c_val = internal_buffer[2 * d_state + state_idx];
                input_val = internal_buffer[3 * d_state + (operation_counter % seq_len)];

                // State update: h_t = A * h_{t-1} + B * x_t
                state_update = (a_val * internal_buffer[4 * d_state + state_idx]) + (b_val * input_val);

                // Store updated state
                internal_buffer[4 * d_state + state_idx] = state_update;

                // Output: y_t = C * h_t + D * x_t  
                pe_data_in[pe_idx] = (c_val * state_update) + 
                                   (internal_buffer[5 * d_state] * input_val);
            end
        end
    end
endtask

// Activation function application
task perform_activation;
    integer pe_idx;
    reg [9:0] lut_addr;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                // Map input to LUT address range
                lut_addr = (internal_buffer[buffer_read_addr] >> (DATA_WIDTH - 10)) & 10'h3FF;
                pe_data_in[pe_idx] = activation_lut[lut_addr];
                buffer_read_addr = (buffer_read_addr + 1) % 4096;
            end
        end
    end
endtask

// Matrix transpose implementation
task perform_transpose;
    integer pe_idx, src_row, src_col, dst_row, dst_col;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                src_row = (operation_counter * NUM_PES + pe_idx) / d_model;
                src_col = (operation_counter * NUM_PES + pe_idx) % d_model;

                if (src_row < d_state && src_col < d_model) begin
                    dst_row = src_col;
                    dst_col = src_row;

                    pe_data_in[pe_idx] = internal_buffer[src_row * d_model + src_col];
                    // Result will be stored at transposed location
                end
            end
        end
    end
endtask

// Reduction sum implementation  
task perform_reduce_sum;
    integer pe_idx, sum_idx;
    reg [DATA_WIDTH-1:0] partial_sum;

    begin
        partial_sum = 0;

        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            sum_idx = operation_counter * NUM_PES + pe_idx;

            if (sum_idx < d_model) begin
                partial_sum = partial_sum + internal_buffer[sum_idx % 4096];
            end
        end

        // Store partial sum
        internal_buffer[buffer_write_addr] = partial_sum;
        buffer_write_addr = (buffer_write_addr + 1) % 4096;
    end
endtask

// Element-wise multiplication
task perform_elementwise_multiply;
    integer pe_idx, elem_idx;

    begin
        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                elem_idx = operation_counter * NUM_PES + pe_idx;

                if (elem_idx < (d_model * seq_len)) begin
                    pe_data_in[pe_idx] = internal_buffer[elem_idx % 2048] * 
                                       internal_buffer[(elem_idx % 2048) + 2048];
                end
            end
        end
    end
endtask

// Layer normalization implementation
task perform_layer_norm;
    integer pe_idx, elem_idx;
    reg [DATA_WIDTH-1:0] mean_val, var_val, normalized;

    begin
        // Simplified layer norm (mean and variance would be pre-computed)
        mean_val = internal_buffer; // Stored mean
        var_val = internal_buffer;  // Stored variance

        for (pe_idx = 0; pe_idx < NUM_PES; pe_idx = pe_idx + 1) begin
            if (pe_ready[pe_idx]) begin
                elem_idx = operation_counter * NUM_PES + pe_idx;

                if (elem_idx < d_model) begin
                    // Normalize: (x - mean) / sqrt(var + epsilon)
                    normalized = (internal_buffer[elem_idx] - mean_val);
                    // Simplified division using bit shift (assumes var is power of 2)
                    pe_data_in[pe_idx] = normalized >> $clog2(var_val + 1);
                end
            end
        end
    end
endtask

// Helper functions
function operand_loading_complete;
    begin
        operand_loading_complete = (current_batch >= batch_size - 1) && 
                                 (current_seq >= seq_len - 1) && 
                                 (current_dim >= d_model - 1);
    end
endfunction

function computation_complete;
    begin
        case (operation)
            OP_MATMUL: 
                computation_complete = operation_counter >= ((batch_size * d_model * d_state) / NUM_PES);
            OP_SSM_SCAN:
                computation_complete = operation_counter >= seq_len;
            default:
                computation_complete = operation_counter >= ((batch_size * seq_len * d_model) / NUM_PES);
        endcase
    end
endfunction

function result_stored;
    begin
        result_stored = (buffer_write_addr > 0) || (current_batch >= batch_size - 1);
    end
endfunction

endmodule

// Processing element implementation
module processing_element #(
    parameter DATA_WIDTH = 16,
    parameter PE_ID = 0
)(
    input wire clk,
    input wire rst_n,
    input wire enable,
    input wire [DATA_WIDTH-1:0] data_in,
    output reg [DATA_WIDTH-1:0] data_out,
    output reg valid_out,
    output wire ready
);

reg [DATA_WIDTH-1:0] acc_reg;
reg [2:0] state;
reg [3:0] cycle_counter;

assign ready = (state == 0) && enable;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_out <= 0;
        valid_out <= 0;
        acc_reg <= 0;
        state <= 0;
        cycle_counter <= 0;
    end else if (enable) begin
        case (state)
            0: begin // IDLE
                if (ready && (data_in != 0)) begin
                    acc_reg <= data_in;
                    state <= 1;
                    cycle_counter <= 0;
                end
            end

            1: begin // PROCESSING
                // Simulate computation latency
                acc_reg <= acc_reg + (data_in >> 2); // Simple MAC operation
                cycle_counter <= cycle_counter + 1;

                if (cycle_counter >= 3) begin // 4-cycle latency
                    state <= 2;
                end
            end

            2: begin // OUTPUT
                data_out <= acc_reg;
                valid_out <= 1;
                state <= 0;
            end
        endcase
    end
end

endmodule

// Async FIFO implementation  
module async_fifo #(
    parameter DATA_WIDTH = 16,
    parameter ADDR_WIDTH = 10
)(
    input wire wr_clk,
    input wire rd_clk,
    input wire rst_n,
    input wire wr_en,
    input wire rd_en,
    input wire [DATA_WIDTH-1:0] data_in,
    output reg [DATA_WIDTH-1:0] data_out,
    output wire empty,
    output wire full
);

localparam DEPTH = 2**ADDR_WIDTH;

reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];
reg  wr_ptr, rd_ptr;
reg  wr_ptr_gray, rd_ptr_gray;
reg  wr_ptr_sync, rd_ptr_sync;

// Gray code counters
always_ff @(posedge wr_clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_ptr <= 0;
        wr_ptr_gray <= 0;
    end else if (wr_en && !full) begin
        wr_ptr <= wr_ptr + 1;
        wr_ptr_gray <= (wr_ptr + 1) ^ ((wr_ptr + 1) >> 1);
    end
end

always_ff @(posedge rd_clk or negedge rst_n) begin
    if (!rst_n) begin
        rd_ptr <= 0;
        rd_ptr_gray <= 0;
    end else if (rd_en && !empty) begin
        rd_ptr <= rd_ptr + 1;
        rd_ptr_gray <= (rd_ptr + 1) ^ ((rd_ptr + 1) >> 1);
    end
end

// Memory operations
always_ff @(posedge wr_clk) begin
    if (wr_en && !full) begin
        memory[wr_ptr[ADDR_WIDTH-1:0]] <= data_in;
    end
end

always_ff @(posedge rd_clk) begin
    if (rd_en && !empty) begin
        data_out <= memory[rd_ptr[ADDR_WIDTH-1:0]];
    end
end

// Synchronizers for cross-clock domain
always_ff @(posedge wr_clk or negedge rst_n) begin
    if (!rst_n)
        rd_ptr_sync <= 0;
    else
        rd_ptr_sync <= rd_ptr_gray;
end

always_ff @(posedge rd_clk or negedge rst_n) begin
    if (!rst_n)
        wr_ptr_sync <= 0;
    else
        wr_ptr_sync <= wr_ptr_gray;
end

// Status flags
assign full = (wr_ptr_gray == {~rd_ptr_sync[ADDR_WIDTH:ADDR_WIDTH-1], rd_ptr_sync[ADDR_WIDTH-2:0]});
assign empty = (rd_ptr_gray == wr_ptr_sync);

endmodule
