    % Test training diagnosis
    diagnose_training_issue(jade_ssm, [loss_not_decreasing, gradient_explosion], Diagnosis),
    format('✓ Training diagnosis: ~w~n', [Diagnosis]),

    % Test optimization suggestions
    optimization_suggestion(jade_ssm, config(32, 2048, 8192), Suggestion),
    format('✓ Optimization suggestion: ~w~n', [Suggestion]),

    % Test question answering
    query_system(['What', 'is', 'SSM', '?'], Answer),
