// JAIDE V25 - Advanced Byte-Pair Encoding Tokenizer
// Implements state-of-the-art tokenization with adaptive vocabulary

use std::collections::{HashMap, HashSet, BinaryHeap};
use std::cmp::Reverse;
use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use serde::{Deserialize, Serialize};
use regex::Regex;
use unicode_normalization::UnicodeNormalization;
use rayon::prelude::*;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TokenizerConfig {
    pub vocab_size: usize,
    pub min_frequency: u32,
    pub special_tokens: Vec<String>,
    pub normalization: String,
    pub pre_tokenization: String,
    pub byte_fallback: bool,
    pub dropout: Option<f64>,
    pub unk_token: String,
    pub bos_token: String,
    pub eos_token: String,
    pub pad_token: String,
    pub mask_token: String,
}

impl Default for TokenizerConfig {
    fn default() -> Self {
        Self {
            vocab_size: 50000,
            min_frequency: 2,
            special_tokens: vec![
                "<unk>".to_string(),
                "<s>".to_string(),
                "</s>".to_string(),
                "<pad>".to_string(),
                "<mask>".to_string(),
            ],
            normalization: "NFC".to_string(),
            pre_tokenization: "whitespace_punctuation".to_string(),
            byte_fallback: true,
            dropout: None,
            unk_token: "<unk>".to_string(),
            bos_token: "<s>".to_string(),
            eos_token: "</s>".to_string(),
            pad_token: "<pad>".to_string(),
            mask_token: "<mask>".to_string(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BPEPair {
    pub left: String,
    pub right: String,
    pub merged: String,
    pub frequency: u64,
}

#[derive(Debug, Clone)]
pub struct TokenStats {
    pub token: String,
    pub frequency: u64,
    pub avg_length: f32,
    pub entropy: f32,
}

#[derive(Debug)]
pub struct JaideBPETokenizer {
    pub config: TokenizerConfig,
    pub vocab: HashMap<String, u32>,
    pub reverse_vocab: HashMap<u32, String>,
    pub merges: Vec<BPEPair>,
    pub special_token_ids: HashMap<String, u32>,
    pub regex_patterns: Vec<Regex>,
    pub char_frequencies: HashMap<char, u64>,
    pub subword_frequencies: HashMap<String, u64>,
}

impl JaideBPETokenizer {
    pub fn new(config: TokenizerConfig) -> Self {
        let mut tokenizer = Self {
            config: config.clone(),
            vocab: HashMap::new(),
            reverse_vocab: HashMap::new(),
            merges: Vec::new(),
            special_token_ids: HashMap::new(),
            regex_patterns: Self::create_regex_patterns(&config),
            char_frequencies: HashMap::new(),
            subword_frequencies: HashMap::new(),
        };

        tokenizer.initialize_special_tokens();
        tokenizer
    }

    fn create_regex_patterns(config: &TokenizerConfig) -> Vec<Regex> {
        let mut patterns = Vec::new();

        match config.pre_tokenization.as_str() {
            "whitespace_punctuation" => {
                patterns.push(Regex::new(r"\p{L}+").unwrap());
                patterns.push(Regex::new(r"\p{N}+").unwrap());
                patterns.push(Regex::new(r"\p{P}").unwrap());
                patterns.push(Regex::new(r"\s+").unwrap());
            }
            "aggressive" => {
                patterns.push(Regex::new(r"[^\s\p{P}]+").unwrap());
                patterns.push(Regex::new(r"\p{P}").unwrap());
            }
            _ => {
                patterns.push(Regex::new(r"\S+").unwrap());
            }
        }

        patterns
    }

    fn initialize_special_tokens(&mut self) {
        let mut token_id = 0;

        for special_token in &self.config.special_tokens {
            self.vocab.insert(special_token.clone(), token_id);
            self.reverse_vocab.insert(token_id, special_token.clone());
            self.special_token_ids.insert(special_token.clone(), token_id);
            token_id += 1;
        }
    }

    pub fn train_from_file(&mut self, file_path: &str) -> Result<(), Box<dyn std::error::Error>> {
        println!("Training BPE tokenizer from file: {}", file_path);

        let file = File::open(file_path)?;
        let reader = BufReader::new(file);

        let mut corpus = Vec::new();
        let mut total_chars = 0;

        // Read and preprocess corpus
        for line in reader.lines() {
            let line = line?;
            let normalized = self.normalize_text(&line);
            let pre_tokenized = self.pre_tokenize(&normalized);

            for word in pre_tokenized {
                total_chars += word.len();
                corpus.push(word);
            }
        }

        println!("Loaded corpus with {} words, {} total characters", corpus.len(), total_chars);

        // Count character frequencies
        self.count_character_frequencies(&corpus);

        // Initialize vocabulary with characters
        self.initialize_character_vocabulary();

        // Learn BPE merges
        self.learn_bpe_merges(&corpus)?;

        println!("Training completed. Final vocabulary size: {}", self.vocab.len());
        Ok(())
    }

    fn normalize_text(&self, text: &str) -> String {
        match self.config.normalization.as_str() {
            "NFC" => text.nfc().collect(),
            "NFD" => text.nfd().collect(),
            "NFKC" => text.nfkc().collect(),
            "NFKD" => text.nfkd().collect(),
            _ => text.to_string(),
        }
    }

    fn pre_tokenize(&self, text: &str) -> Vec<String> {
        let mut tokens = Vec::new();
        let mut current_pos = 0;

        while current_pos < text.len() {
            let mut matched = false;

            for pattern in &self.regex_patterns {
                if let Some(mat) = pattern.find(&text[current_pos..]) {
                    if mat.start() == 0 {
                        let token = mat.as_str().to_string();
                        tokens.push(token);
                        current_pos += mat.end();
                        matched = true;
                        break;
                    }
                }
            }

            if !matched {
                // Fallback: take next character
                if let Some(ch) = text[current_pos..].chars().next() {
                    tokens.push(ch.to_string());
                    current_pos += ch.len_utf8();
                } else {
                    break;
                }
            }
        }

        tokens
    }

    fn count_character_frequencies(&mut self, corpus: &[String]) {
        for word in corpus {
            for ch in word.chars() {
                *self.char_frequencies.entry(ch).or_insert(0) += 1;
            }
        }
    }

    fn initialize_character_vocabulary(&mut self) {
        let mut token_id = self.special_token_ids.len() as u32;

        // Add characters to vocabulary based on frequency
        let mut char_freq_vec: Vec<_> = self.char_frequencies.iter().collect();
        char_freq_vec.sort_by(|a, b| b.1.cmp(a.1));

        for (&ch, &freq) in char_freq_vec {
            if freq >= self.config.min_frequency as u64 {
                let char_str = ch.to_string();
                self.vocab.insert(char_str.clone(), token_id);
                self.reverse_vocab.insert(token_id, char_str);
                token_id += 1;
            }
        }

        // Add byte fallback tokens if enabled
        if self.config.byte_fallback {
            for byte_val in 0u8..=255 {
                let byte_token = format!("<0x{:02X}>", byte_val);
                if !self.vocab.contains_key(&byte_token) {
                    self.vocab.insert(byte_token.clone(), token_id);
                    self.reverse_vocab.insert(token_id, byte_token);
                    token_id += 1;
                }
            }
        }
    }

    fn learn_bpe_merges(&mut self, corpus: &[String]) -> Result<(), Box<dyn std::error::Error>> {
        // Convert corpus to subword representation
        let mut subword_corpus: Vec<Vec<String>> = corpus
            .par_iter()
            .map(|word| self.word_to_subwords(word))
            .collect();

        let target_vocab_size = self.config.vocab_size;
        let mut current_vocab_size = self.vocab.len();

        println!("Starting BPE learning. Initial vocab size: {}", current_vocab_size);

        while current_vocab_size < target_vocab_size {
            // Count all possible pairs
            let pair_counts = self.count_pairs(&subword_corpus);

            if pair_counts.is_empty() {
                println!("No more pairs to merge. Stopping.");
                break;
            }

            // Find the most frequent pair
            let best_pair = pair_counts
                .iter()
                .max_by_key(|(_, &count)| count)
                .unwrap();

            let (left, right) = best_pair.0;
            let frequency = *best_pair.1;

            if frequency < self.config.min_frequency as u64 {
                println!("Frequency threshold reached. Stopping.");
                break;
            }

            // Create merged token
            let merged_token = format!("{}{}", left, right);
            let token_id = current_vocab_size as u32;

            // Add to vocabulary
            self.vocab.insert(merged_token.clone(), token_id);
            self.reverse_vocab.insert(token_id, merged_token.clone());

            // Record the merge
            let bpe_pair = BPEPair {
                left: left.clone(),
                right: right.clone(),
                merged: merged_token.clone(),
                frequency,
            };
            self.merges.push(bpe_pair);

            // Apply merge to corpus
            self.apply_merge_to_corpus(&mut subword_corpus, left, right, &merged_token);

            current_vocab_size += 1;

            if current_vocab_size % 1000 == 0 {
                println!("Vocabulary size: {} / {}", current_vocab_size, target_vocab_size);
            }
        }

        println!("BPE learning completed. Final vocabulary size: {}", current_vocab_size);
        Ok(())
    }

    fn word_to_subwords(&self, word: &str) -> Vec<String> {
        let mut subwords = Vec::new();
        let mut i = 0;
        let chars: Vec<char> = word.chars().collect();

        while i < chars.len() {
            let mut found_match = false;

            // Try to find the longest matching subword starting at position i
            for j in ((i + 1)..=chars.len()).rev() {
                let potential_subword: String = chars[i..j].iter().collect();

                if self.vocab.contains_key(&potential_subword) {
                    subwords.push(potential_subword);
                    i = j;
                    found_match = true;
                    break;
                }
            }

            if !found_match {
                // Fallback to single character or byte representation
                let ch = chars[i];
                if self.vocab.contains_key(&ch.to_string()) {
                    subwords.push(ch.to_string());
                } else if self.config.byte_fallback {
                    // Convert to byte representation
                    let mut byte_buffer = [0; 4];
                    let byte_str = ch.encode_utf8(&mut byte_buffer);
                    for &byte_val in byte_str.as_bytes() {
                        let byte_token = format!("<0x{:02X}>", byte_val);
                        subwords.push(byte_token);
                    }
                } else {
                    subwords.push(self.config.unk_token.clone());
                }
                i += 1;
            }
        }

        subwords
    }

    fn count_pairs(&self, corpus: &[Vec<String>]) -> HashMap<(String, String), u64> {
        let mut pair_counts = HashMap::new();

        for subwords in corpus {
            for window in subwords.windows(2) {
                if let [left, right] = window {
                    let pair = (left.clone(), right.clone());
                    *pair_counts.entry(pair).or_insert(0) += 1;
                }
            }
        }

        pair_counts
    }

    fn apply_merge_to_corpus(
        &self,
        corpus: &mut [Vec<String>],
        left: &str,
        right: &str,
        merged: &str,
    ) {
        corpus.par_iter_mut().for_each(|subwords| {
            let mut i = 0;
            while i < subwords.len().saturating_sub(1) {
                if subwords[i] == left && subwords[i + 1] == right {
                    // Merge the pair
                    subwords[i] = merged.to_string();
                    subwords.remove(i + 1);
                } else {
                    i += 1;
                }
            }
        });
    }

    pub fn encode(&self, text: &str) -> Vec<u32> {
        let normalized = self.normalize_text(text);
        let pre_tokenized = self.pre_tokenize(&normalized);

        let mut token_ids = Vec::new();

        // Add BOS token if configured
        if !self.config.bos_token.is_empty() {
            if let Some(&token_id) = self.special_token_ids.get(&self.config.bos_token) {
                token_ids.push(token_id);
            }
        }

        for word in pre_tokenized {
            let subwords = self.encode_word(&word);
            token_ids.extend(subwords);
        }

        // Add EOS token if configured
        if !self.config.eos_token.is_empty() {
            if let Some(&token_id) = self.special_token_ids.get(&self.config.eos_token) {
                token_ids.push(token_id);
            }
        }

        token_ids
    }

    fn encode_word(&self, word: &str) -> Vec<u32> {
        let mut subwords = self.word_to_subwords(word);

        // Apply BPE merges in order
        for merge in &self.merges {
            let mut i = 0;
            while i < subwords.len().saturating_sub(1) {
                if subwords[i] == merge.left && subwords[i + 1] == merge.right {
                    subwords[i] = merge.merged.clone();
                    subwords.remove(i + 1);
                } else {
                    i += 1;
                }
            }
        }

        // Apply dropout if configured
        if let Some(dropout_prob) = self.config.dropout {
            subwords = self.apply_dropout(subwords, dropout_prob);
        }

        // Convert to token IDs
        subwords
            .into_iter()
            .map(|token| {
                self.vocab
                    .get(&token)
                    .copied()
                    .unwrap_or_else(|| {
                        self.special_token_ids
                            .get(&self.config.unk_token)
                            .copied()
                            .unwrap_or(0)
                    })
            })
            .collect()
    }

    fn apply_dropout(&self, mut subwords: Vec<String>, dropout_prob: f64) -> Vec<String> {
        use rand::Rng;
        let mut rng = rand::thread_rng();

        let mut i = 0;
        while i < subwords.len().saturating_sub(1) {
            if rng.gen::<f64>() < dropout_prob {
                // Randomly decide whether to split this subword
                if let Some(original_pair) = self.find_original_pair(&subwords[i]) {
                    subwords[i] = original_pair.0;
                    subwords.insert(i + 1, original_pair.1);
                    i += 2;
                } else {
                    i += 1;
                }
            } else {
                i += 1;
            }
        }

        subwords
    }

    fn find_original_pair(&self, merged_token: &str) -> Option<(String, String)> {
        for merge in &self.merges {
            if merge.merged == merged_token {
                return Some((merge.left.clone(), merge.right.clone()));
            }
        }
        None
    }

    pub fn decode(&self, token_ids: &[u32]) -> String {
        let tokens: Vec<String> = token_ids
            .iter()
            .filter_map(|&id| self.reverse_vocab.get(&id))
            .cloned()
            .collect();

        self.decode_tokens(&tokens)
    }

    fn decode_tokens(&self, tokens: &[String]) -> String {
        let mut result = String::new();

        for token in tokens {
            // Skip special tokens in output
            if self.special_token_ids.contains_key(token) {
                if token == &self.config.bos_token || token == &self.config.eos_token {
                    continue;
                }
                if token == &self.config.pad_token {
                    continue;
                }
            }

            // Handle byte tokens
            if token.starts_with("<0x") && token.ends_with(">") {
                if let Ok(byte_val) = u8::from_str_radix(&token[3..5], 16) {
                    result.push(byte_val as char);
                }
            } else {
                result.push_str(token);
            }
        }

        // Post-process to fix spacing
        self.post_process_decoded(&result)
    }

    fn post_process_decoded(&self, text: &str) -> String {
        // Simple post-processing to restore proper spacing
        text.replace(" ##", "")
            .replace("##", "")
            .trim()
            .to_string()
    }

    pub fn save(&self, path: &str) -> Result<(), Box<dyn std::error::Error>> {
        let serialized = serde_json::to_string_pretty(&TokenizerData {
            config: &self.config,
            vocab: &self.vocab,
            merges: &self.merges,
            special_token_ids: &self.special_token_ids,
        })?;

        let mut file = File::create(path)?;
        file.write_all(serialized.as_bytes())?;

        println!("Tokenizer saved to: {}", path);
        Ok(())
    }

    pub fn load(path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        let data: TokenizerData = serde_json::from_reader(reader)?;

        let mut reverse_vocab = HashMap::new();
        for (token, &id) in &data.vocab {
            reverse_vocab.insert(id, token.clone());
        }

        let regex_patterns = Self::create_regex_patterns(&data.config);

        Ok(Self {
            config: data.config,
            vocab: data.vocab,
            reverse_vocab,
            merges: data.merges,
            special_token_ids: data.special_token_ids,
            regex_patterns,
            char_frequencies: HashMap::new(),
            subword_frequencies: HashMap::new(),
        })
    }

    pub fn get_vocab_size(&self) -> usize {
        self.vocab.len()
    }

    pub fn get_token_frequency(&self, token: &str) -> Option<u64> {
        self.subword_frequencies.get(token).copied()
    }

    pub fn get_vocab_stats(&self) -> Vec<TokenStats> {
        let mut stats = Vec::new();

        for (token, &_id) in &self.vocab {
            let frequency = self.get_token_frequency(token).unwrap_or(0);
            let avg_length = token.len() as f32;
            let entropy = self.calculate_token_entropy(token);

            stats.push(TokenStats {
                token: token.clone(),
                frequency,
                avg_length,
                entropy,
            });
        }

        stats.sort_by(|a, b| b.frequency.cmp(&a.frequency));
        stats
    }

    fn calculate_token_entropy(&self, token: &str) -> f32 {
        let char_counts: HashMap<char, usize> = token
            .chars()
            .fold(HashMap::new(), |mut acc, ch| {
                *acc.entry(ch).or_insert(0) += 1;
                acc
            });

        let total_chars = token.len() as f32;
        let mut entropy = 0.0;

        for &count in char_counts.values() {
            let probability = count as f32 / total_chars;
            entropy -= probability * probability.log2();
        }

        entropy
    }

    pub fn encode_batch(&self, texts: &[String]) -> Vec<Vec<u32>> {
        texts
            .par_iter()
            .map(|text| self.encode(text))
            .collect()
    }

    pub fn decode_batch(&self, token_ids_batch: &[Vec<u32>]) -> Vec<String> {
        token_ids_batch
            .par_iter()
            .map(|token_ids| self.decode(token_ids))
            .collect()
    }

    pub fn pad_sequences(&self, sequences: &[Vec<u32>], max_length: Option<usize>) -> Vec<Vec<u32>> {
        let pad_token_id = self
            .special_token_ids
            .get(&self.config.pad_token)
            .copied()
            .unwrap_or(0);

        let max_len = max_length.unwrap_or_else(|| {
            sequences.iter().map(|seq| seq.len()).max().unwrap_or(0)
        });

        sequences
            .iter()
            .map(|seq| {
                let mut padded = seq.clone();
                while padded.len() < max_len {
                    padded.push(pad_token_id);
                }
                padded.truncate(max_len);
                padded
            })
            .collect()
    }
}

#[derive(Serialize, Deserialize)]
struct TokenizerData<'a> {
    config: &'a TokenizerConfig,
    vocab: &'a HashMap<String, u32>,
    merges: &'a Vec<BPEPair>,
    special_token_ids: &'a HashMap<String, u32>,
}

// Testing and benchmarking
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_encoding_decoding() {
        let config = TokenizerConfig::default();
        let mut tokenizer = JaideBPETokenizer::new(config);

        // Initialize with basic vocabulary
        tokenizer.vocab.insert("h".to_string(), 5);
        tokenizer.vocab.insert("e".to_string(), 6);
        tokenizer.vocab.insert("l".to_string(), 7);
        tokenizer.vocab.insert("o".to_string(), 8);
        tokenizer.reverse_vocab.insert(5, "h".to_string());
        tokenizer.reverse_vocab.insert(6, "e".to_string());
        tokenizer.reverse_vocab.insert(7, "l".to_string());
        tokenizer.reverse_vocab.insert(8, "o".to_string());

        let text = "hello";
        let encoded = tokenizer.encode(text);
        let decoded = tokenizer.decode(&encoded);

        assert!(decoded.contains("hello") || encoded.len() > 0);
    }

    #[test]
    fn test_special_tokens() {
        let config = TokenizerConfig::default();
        let tokenizer = JaideBPETokenizer::new(config);

        assert!(tokenizer.special_token_ids.contains_key("<unk>"));
        assert!(tokenizer.special_token_ids.contains_key("<s>"));
        assert!(tokenizer.special_token_ids.contains_key("</s>"));
    }

    #[test]
    fn test_normalization() {
        let config = TokenizerConfig::default();
        let tokenizer = JaideBPETokenizer::new(config);

        let text = "café";
        let normalized = tokenizer.normalize_text(text);

        assert_eq!(normalized.len(), text.len());
    }
}

// CLI interface for the tokenizer
pub fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        println!("Usage: {} <command> [args...]", args);
        println!("Commands:");
        println!("  train <corpus_file> <output_model>");
        println!("  encode <model_file> <text>");
        println!("  decode <model_file> <token_ids>");
        return Ok(());
    }

    match args[1].as_str() {
        "train" => {
            if args.len() != 4 {
                eprintln!("Usage: {} train <corpus_file> <output_model>", args);
                return Ok(());
            }

            let mut config = TokenizerConfig::default();
            config.vocab_size = 32000; // Default for training

            let mut tokenizer = JaideBPETokenizer::new(config);
            tokenizer.train_from_file(&args)?;
            tokenizer.save(&args)?;

            println!("Training completed. Model saved to {}", args);
        }

        "encode" => {
            if args.len() != 4 {
                eprintln!("Usage: {} encode <model_file> <text>", args);
                return Ok(());
            }

            let tokenizer = JaideBPETokenizer::load(&args)?;
            let encoded = tokenizer.encode(&args);

            println!("Encoded: {:?}", encoded);
        }

        "decode" => {
            if args.len() != 4 {
                eprintln!("Usage: {} decode <model_file> <token_ids>", args);
                return Ok(());
            }

            let tokenizer = JaideBPETokenizer::load(&args)?;
            let token_ids: Vec<u32> = args
                .split(',')
                .filter_map(|s| s.trim().parse().ok())
                .collect();

            let decoded = tokenizer.decode(&token_ids);
            println!("Decoded: {}", decoded);
        }

        _ => {
            eprintln!("Unknown command: {}", args[1]);
        }
    }

    Ok(())
}
